# Regex para extrair os dados
regex = r"→ Epoch (\d+): Train Loss: (\d+\.\d+), Val Loss: (\d+\.\d+), Melanoma Recall: (\d+\.\d+)"
matches = re.findall(regex, data_string)

# Criar um DataFrame a partir dos dados extraídos
df = pd.DataFrame(matches, columns=['Epoch', 'Train Loss', 'Val Loss', 'Melanoma Recall'])
df = df.astype({'Epoch': int, 'Train Loss': float, 'Val Loss': float, 'Melanoma Recall': float})

# Criar o plot
plt.style.use('seaborn-v0_8-whitegrid')
fig, ax1 = plt.subplots(figsize=(12, 8))

# Plotar as perdas (Loss) no eixo Y esquerdo
ax1.set_xlabel('Epoch', fontsize=12)
ax1.set_ylabel('Loss', color='tab:red', fontsize=12)
ax1.plot(df['Epoch'], df['Train Loss'], 'tab:red', label='Train Loss', marker='o')
ax1.plot(df['Epoch'], df['Val Loss'], 'tab:purple', label='Val Loss', marker='s')
ax1.tick_params(axis='y', labelcolor='tab:red')

# Criar um segundo eixo Y para o Recall de Melanoma
ax2 = ax1.twinx()
ax2.set_ylabel('Melanoma Recall', color='tab:blue', fontsize=12)
ax2.plot(df['Epoch'], df['Melanoma Recall'], 'tab:blue', label='Melanoma Recall', marker='^')
ax2.tick_params(axis='y', labelcolor='tab:blue')

# Adicionar título e legenda
plt.title('Desempenho do Modelo ao Longo das Épocas', fontsize=16)
fig.legend(loc="upper right", bbox_to_anchor=(1,1), bbox_transform=ax1.transAxes)

# Salvar e mostrar o plot
plt.grid(True)
plt.tight_layout()
plt.savefig('performance_plot.png')
